13	// The tests of Destroy (DEVDESK-504, step 7, risk R1: deleting a namespace is
14	// irreversible). Destroy is called as
15	//
16	//	Destroy(ctx, runner, clock, store, p, out) error
17	//
18	// against the scripted kubectl of preflight_test.go, wrapped by destroyKubectl
19	// below, which adds the two things Destroy needs and the preflight does not:
20	// the one write the bench may issue, and the reads that follow it. No real
21	// kubectl, no real wait: the Clock is fakeClock (clock_test.go).
22	//
23	// The kubectl calls the tests assume (arguments after "kubectl", without
24	// --context; "--request-timeout=<d>" may sit anywhere and is ignored):
25	//
26	//	config get-contexts -o name        \  RunPreflight(OpDown), first, always:
27	//	get --raw /readyz                   |  Destroy goes through it and nothing is
28	//	auth can-i delete namespaces        |  written when it fails
29	//	get namespace <ns> -o json         /
30	//	delete namespace <ns> --wait=false    the only write; at most once per Destroy
31	//	get namespace <ns> -o json            polled, with Clock.Sleep between polls,
32	//	                                      until NotFound or p.DeleteTimeout
33	//	get pv -o json                        read once, after the namespace is gone
34	//
35	// Anything else fails the test as unscripted. In particular a second write
36	// (a finalizer patch, a force delete, a delete of anything but the namespace)
37	// is caught by the "exactly one write" checks.
38	//
39	// Hypotheses about what Destroy says, to settle with the code:
40	//   - an absent namespace prints a line containing "nothing to delete";
41	//   - a PV left bound to the namespace prints a line containing "warning" and
42	//     the PV name (case-insensitive for "warning"); without one, no "warning";
43	//   - the Deadline message names the remaining finalizers of spec.finalizers
44	//     and, for status.conditions, either the type or the message of a condition;
45	//   - the namespace is polled at least once per second at most (an interval of
46	//     1 s or more) and at most every 30 s, so the wait ends within 30 s of
47	//     p.DeleteTimeout;
48	//   - a failure to remove the secrets and an unreadable PV list are not tested.
49	
50	// ---- doubles ----------------------------------------------------------------
51	
52	// fakePV is one PersistentVolume of the cluster.
53	type fakePV struct {
54		name, claimNamespace, claimName, phase string
55	}
56	
57	// destroyKubectl wraps the scripted kubectl: reads go to it until the namespace
58	// is deleted; the delete itself and what follows are answered here.
59	type destroyKubectl struct {
60		*fakeKubectl
61		log *orderLog
62	
63		// terminatingPolls is how many "get namespace" after the delete answer
64		// Terminating before NotFound; -1 means it never goes away.
65		terminatingPolls int
66		finalizers       []string
67		conditions       []map[string]any
68	
69		pvs     []fakePV
70		pvReply *fakeReply // when set, answers "get pv -o json"
71	
72		deleteReply *fakeReply // when set, answers the delete instead of accepting it
73	
74		deleted        bool
75		namespacePolls int // "get namespace" calls after the delete
76		pvReads        int
77		lines          []string // every call, normalized, in order
78		writes         []string // every call whose sub-command writes
79	}
80	
81	var _ Runner = (*destroyKubectl)(nil)
82	
83	func newDestroyKubectl(t *testing.T, p Params, log *orderLog) *destroyKubectl {
84		t.Helper()
85		return &destroyKubectl{
86			fakeKubectl:      newFakeKubectl(t, p),
87			log:              log,
88			terminatingPolls: 2,
89			finalizers:       []string{"kubernetes"},
90			conditions: []map[string]any{{
91				"type":    "NamespaceContentRemaining",
92				"status":  "True",
93				"reason":  "SomeResourcesRemain",
94				"message": "Some resources are remaining: persistentvolumeclaims. has 1 resource instances",
95			}},
96		}
97	}
98	
99	func (d *destroyKubectl) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
100		norm := normalizeArgs(args)
101		joined := strings.Join(norm, " ")
102		d.lines = append(d.lines, joined)
103		d.log.add("KUBECTL " + joined)
104		ns := d.p.Namespace
105	
106		switch verb := verbOf(args); {
107		case verb == "delete":
108			d.writes = append(d.writes, joined)
109			if joined != "delete namespace "+ns+" --wait=false" {
110				d.t.Errorf("unexpected delete call %q, the only write allowed is `delete namespace %s --wait=false`", args, ns)
111				return nil, []byte("the fake refuses this delete"), errFakeExit1
112			}
113			if d.deleteReply != nil {
114				return d.deleteReply.reply()
115			}
116			d.deleted = true
117			return []byte("namespace \"" + ns + "\" deleted\n"), nil, nil
118		case isWriteVerb(verb):
119			d.writes = append(d.writes, joined)
120			d.t.Errorf("unexpected write call %q", args)
121			return nil, []byte("the fake refuses a write: " + verb), errFakeExit1
122		case joined == "get namespace "+ns+" -o json" && d.deleted:
123			return d.answerAfterDelete()
124		case joined == "get pv -o json":
125			d.pvReads++
126			return d.answerPVs()
127		}
128		return d.fakeKubectl.Run(ctx, stdin, args...)
129	}
130	
131	func (d *destroyKubectl) answerAfterDelete() ([]byte, []byte, error) {
132		d.namespacePolls++
133		if d.terminatingPolls >= 0 && d.namespacePolls > d.terminatingPolls {
134			return nil, []byte("Error from server (NotFound): namespaces \"" + d.p.Namespace + "\" not found\n"), errFakeExit1
135		}
136		return d.mustJSON(map[string]any{
137			"apiVersion": "v1",
138			"kind":       "Namespace",
139			"metadata": map[string]any{
140				"name":              d.p.Namespace,
141				"labels":            map[string]string{managedByKV: benchOwner, "kubernetes.io/metadata.name": d.p.Namespace},
142				"deletionTimestamp": "2026-11-16T12:00:00Z",
143			},
144			"spec":   map[string]any{"finalizers": d.finalizers},
145			"status": map[string]any{"phase": "Terminating", "conditions": d.conditions},
146		}), nil, nil
147	}
148	
149	func (d *destroyKubectl) answerPVs() ([]byte, []byte, error) {
150		if d.pvReply != nil {
151			return d.pvReply.reply()
152		}
153		items := make([]any, 0, len(d.pvs))
154		for _, pv := range d.pvs {
155			spec := map[string]any{
156				"capacity":                      map[string]string{"storage": "5Gi"},
157				"accessModes":                   []string{"ReadWriteOnce"},
158				"persistentVolumeReclaimPolicy": "Retain",
159				"storageClassName":              "local-path",
160			}
161			if pv.claimNamespace != "" {
162				spec["claimRef"] = map[string]any{"kind": "PersistentVolumeClaim", "namespace": pv.claimNamespace, "name": pv.claimName}
163			}
164			items = append(items, map[string]any{
165				"metadata": map[string]any{"name": pv.name},
166				"spec":     spec,
167				"status":   map[string]any{"phase": pv.phase},
168			})
169		}
170		return d.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
171	}
