239	// preflightLines are the calls RunPreflight(OpDown) makes when the namespace exists or not.
240	func (e *destroyEnv) preflightLines() []string {
241		return []string{
242			"config get-contexts -o name",
243			"get --raw /readyz",
244			"auth can-i delete namespaces",
245			"get namespace " + e.p.Namespace + " -o json",
246		}
247	}
