253	func (e *destroyEnv) requireNoWrite() {
254		e.t.Helper()
255		if len(e.kube.writes) != 0 {
256			e.t.Errorf("Destroy wrote to the cluster: %q", e.kube.writes)
257		}
258	}
259	
260	func (e *destroyEnv) requireOneDelete() {
261		e.t.Helper()
262		if !slices.Equal(e.kube.writes, []string{e.deleteLine()}) {
263			e.t.Errorf("writes = %q, want exactly one: %q", e.kube.writes, e.deleteLine())
264		}
265	}
266	
267	func (e *destroyEnv) requireStoreUntouched() {
268		e.t.Helper()
269		if e.store.removes != 0 {
270			e.t.Errorf("the secrets were removed %d time(s) although Destroy did not succeed", e.store.removes)
271		}
272	}
273	
274	// requireNoSecret checks that nothing Destroy said carries a password or the marker.
275	func (e *destroyEnv) requireNoSecret(err error) {
276		e.t.Helper()
277		said := e.out.String()
278		if err != nil {
279			said += "\n" + err.Error()
280		}
281		for _, banned := range []string{"password", strings.ToLower(secretMarker), strings.ToLower(fakeSecret)} {
282			if strings.Contains(strings.ToLower(said), banned) {
283				e.t.Errorf("Destroy said %q, which contains %q", said, banned)
284			}
285		}
286	}
