288	// requireBenchError checks the failure is a clean *BenchError of the given kind.
289	func requireBenchKind(t *testing.T, err error, kind ErrKind) *BenchError {
290		t.Helper()
291		if err == nil {
292			t.Fatalf("Destroy succeeded, want a BenchError of kind %d", kind)
293		}
294		be := requireCleanError(t, err)
295		if be.Kind != kind {
296			t.Errorf("Kind = %d, want %d; message: %v", be.Kind, kind, err)
297		}
298		return be
299	}
