303	func TestDestroyNamespaceAbsent(t *testing.T) {
304		env := newDestroyEnv(t, Defaults())
305	
306		err := env.destroy(context.Background())
307		if err != nil {
308			t.Fatalf("Destroy of an absent namespace = %v, want success", err)
309		}
310		if !strings.Contains(strings.ToLower(env.out.String()), "nothing to delete") {
311			t.Errorf("output %q does not say there is nothing to delete", env.out.String())
312		}
313		env.requireNoWrite()
314		if got := env.kube.lines; !slices.Equal(got, env.preflightLines()) {
315			t.Errorf("calls = %q, want only the preflight %q", got, env.preflightLines())
316		}
317		if len(env.clk.sleeps) != 0 {
318			t.Errorf("Destroy slept %d times with nothing to wait for", len(env.clk.sleeps))
319		}
320		env.requireNoSecret(err)
321	}
