323	func TestDestroyRefusesAForeignNamespace(t *testing.T) {
324		tests := []struct {
325			name   string
326			labels map[string]string
327		}{
328			{"no label at all", map[string]string{"kubernetes.io/metadata.name": "nexus-bench"}},
329			{"no labels field", nil},
330			{"managed by someone else", map[string]string{managedByKV: "helm", "kubernetes.io/metadata.name": "nexus-bench"}},
331			{"our value under another key", map[string]string{"app.kubernetes.io/part-of": benchOwner}},
332			{"our key with a near value", map[string]string{managedByKV: benchOwner + "-2"}},
333			{"only part of the label is right", map[string]string{managedByKV: ""}},
334		}
335		for _, tt := range tests {
336			t.Run(tt.name, func(t *testing.T) {
337				env := newDestroyEnv(t, Defaults())
338				env.kube.withNamespace(tt.labels)
339	
340				err := env.destroy(context.Background())
341	
342				be := requireBenchKind(t, err, NamespaceForeign)
343				if !strings.Contains(be.Error(), env.p.Namespace) {
344					t.Errorf("message %q does not name the namespace", be.Error())
345				}
346				env.requireNoWrite()
347				if slices.ContainsFunc(env.kube.lines, func(l string) bool { return strings.HasPrefix(l, "delete") }) {
348					t.Errorf("a delete was attempted on a namespace that is not ours: %q", env.kube.lines)
349				}
350				env.requireStoreUntouched()
351				env.requireNoSecret(err)
352			})
353		}
354	}
