356	func TestDestroyDeletesOurNamespace(t *testing.T) {
357		tests := []struct {
358			name             string
359			terminatingPolls int
360		}{
361			{"gone at the first poll", 0},
362			{"terminating for a few polls", 3},
363		}
364		for _, tt := range tests {
365			t.Run(tt.name, func(t *testing.T) {
366				env := ownedEnv(t, Defaults())
367				env.kube.terminatingPolls = tt.terminatingPolls
368	
369				err := env.destroy(context.Background())
370				if err != nil {
371					t.Fatalf("Destroy = %v", err)
372				}
373	
374				// One write, the delete of the namespace, never waited for by kubectl.
375				env.requireOneDelete()
376	
377				// The exact sequence: preflight, delete, polls until NotFound, PVs.
378				want := slices.Clone(env.preflightLines())
379				want = append(want, env.deleteLine())
380				for range tt.terminatingPolls + 1 {
381					want = append(want, "get namespace "+env.p.Namespace+" -o json")
382				}
383				want = append(want, "get pv -o json")
384				if !slices.Equal(env.kube.lines, want) {
385					t.Errorf("calls =\n  %q\nwant\n  %q", env.kube.lines, want)
386				}
387	
388				// The wait goes through the clock: no polling without a sleep between.
389				if got, lo, hi := len(env.clk.sleeps), tt.terminatingPolls, tt.terminatingPolls+1; got < lo || got > hi {
390					t.Errorf("sleeps = %d, want between %d and %d for %d Terminating answers", got, lo, hi, tt.terminatingPolls)
391				}
392				if tt.terminatingPolls > 0 && env.clk.elapsed() <= 0 {
393					t.Error("the fake clock did not advance")
394				}
395				if env.kube.pvReads != 1 {
396					t.Errorf("PV list read %d times, want once", env.kube.pvReads)
397				}
398	
399				// The secrets go last: after the namespace is gone and the PVs checked.
400				if env.store.removes != 1 {
401					t.Errorf("secrets removed %d times, want once", env.store.removes)
402				}
403				rm, pv := env.log.index("STORE Remove"), env.log.index("KUBECTL get pv -o json")
404				del := env.log.index("KUBECTL " + env.deleteLine())
405				if del < 0 || pv < del || rm < pv {
406					t.Errorf("order wrong: delete at %d, PV read at %d, secrets removed at %d; journal: %q", del, pv, rm, env.log.snapshot())
407				}
408	
409				if strings.Contains(strings.ToLower(env.out.String()), "warning") {
410					t.Errorf("output %q warns although no volume is left", env.out.String())
411				}
412				env.requireNoSecret(err)
413			})
414		}
415	}
