435					{"pv-free", "", "", "Available"},
436				},
437				warnAbout: []string{"pvc-2222"},
438				silentOn:  []string{"pvc-other", "pvc-same-name", "pv-free"},
439			},
440			{
441				name: "two volumes are both named",
442				pvs: []fakePV{
443					{"pvc-3333", "nexus-bench", "a", "Released"},
444					{"pvc-4444", "nexus-bench", "b", "Failed"},
445				},
446				warnAbout: []string{"pvc-3333", "pvc-4444"},
447			},
448		}
449		for _, tt := range tests {
450			t.Run(tt.name, func(t *testing.T) {
451				env := ownedEnv(t, Defaults())
452				env.kube.pvs = tt.pvs
453	
454				err := env.destroy(context.Background())
455				if err != nil {
456					t.Fatalf("a leftover volume must warn, not fail; Destroy = %v", err)
457				}
458				said := env.out.String()
459				if !strings.Contains(strings.ToLower(said), "warning") {
460					t.Errorf("output %q has no warning", said)
461				}
