466				}
467				for _, name := range tt.silentOn {
468					if strings.Contains(said, name) {
469						t.Errorf("output %q names %q, a volume that is not bound to the namespace", said, name)
470					}
471				}
472				env.requireOneDelete()
473				// The namespace is gone, so the secrets of it go too.
474				if env.store.removes != 1 {
475					t.Errorf("secrets removed %d times, want once", env.store.removes)
476				}
477				env.requireNoSecret(err)
478			})
