482	func TestDestroyDeadlineWhenTheNamespaceStaysTerminating(t *testing.T) {
483		tests := []struct {
484			name    string
485			timeout time.Duration
486		}{
487			{"default delete timeout", Defaults().DeleteTimeout},
488			{"a short delete timeout is honored", 45 * time.Second},
489		}
490		const slack = 30 * time.Second
491		for _, tt := range tests {
492			t.Run(tt.name, func(t *testing.T) {
493				p := Defaults()
494				p.DeleteTimeout = tt.timeout
495				env := ownedEnv(t, p)
496				env.kube.terminatingPolls = -1
497				env.kube.finalizers = []string{"kubernetes", "example.com/bench-finalizer"}
498	
499				err := env.destroy(context.Background())
500	
501				be := requireBenchKind(t, err, Deadline)
502				msg := err.Error()
503				if !strings.Contains(msg, "example.com/bench-finalizer") {
504					t.Errorf("message %q does not cite the remaining finalizer", msg)
505				}
506				if !strings.Contains(msg, "NamespaceContentRemaining") && !strings.Contains(msg, "persistentvolumeclaims") {
507					t.Errorf("message %q cites neither the type nor the message of the remaining condition", msg)
508				}
509				if !strings.Contains(msg, env.p.Namespace) {
510					t.Errorf("message %q does not name the namespace", msg)
511				}
512				if be.Check == "" {
513					t.Error("the Deadline error has no Check")
514				}
515	
516				// It waited the whole delete timeout, and no longer than that plus one interval.
517				if el := env.clk.elapsed(); el < tt.timeout || el > tt.timeout+slack {
518					t.Errorf("waited %v on the fake clock, want between %v and %v", el, tt.timeout, tt.timeout+slack)
519				}
520				// The number of polls is bounded: one per second at the very most.
521				if limit := int(tt.timeout/time.Second) + 2; env.kube.namespacePolls > limit || env.kube.namespacePolls < 2 {
522					t.Errorf("polled %d times, want between 2 and %d", env.kube.namespacePolls, limit)
523				}
524	
525				// Stuck is not a reason to force it: the one delete, no finalizer patch.
526				env.requireOneDelete()
527				env.requireStoreUntouched()
528				env.requireNoSecret(err)
529			})
530		}
531	}
