551	// Every parameter that names a namespace the bench must never touch is refused
552	// by Validate, before the first kubectl call.
553	func TestDestroyRefusesInvalidParamsBeforeAnyCall(t *testing.T) {
554		for _, ns := range []string{"default", "kube-system", "kube-public", "plane", "traefik"} {
555			t.Run(ns, func(t *testing.T) {
556				p := Defaults()
557				p.Namespace = ns
558				env := newDestroyEnv(t, p)
559				env.kube.ours() // even labeled, the name alone forbids it
560	
561				err := env.destroy(context.Background())
562	
