9	
10	// fakeClock is the Clock of the tests: Sleep never waits, it moves the clock
11	// forward by the requested duration. Destroy (step 7) and the readiness wait
12	// (step 4) run against it, so no test sleeps for real.
13	//
14	// Hypotheses about the Clock contract, which the real clock (clock.go) must keep:
15	//   - Sleep returns ctx.Err() as soon as ctx is done, before and instead of
16	//     sleeping, and nil after sleeping the whole duration;
17	//   - a caller never sleeps for zero or less (that would be a busy loop).
18	type fakeClock struct {
19		t *testing.T
20	
21		now    time.Time
22		sleeps []time.Duration // every Sleep call, in order
23	
24		// onSleep, when set, runs at the start of the n-th Sleep (1-based), before
25		// ctx is looked at: a test cancels the context from it.
26		onSleep func(n int)
27	
28		// maxSleeps stops a runaway loop: past it the fake reports the failure and
29		// returns an error instead of letting the code under test spin forever.
30		maxSleeps int
31	}
32	
33	var _ Clock = (*fakeClock)(nil)
34	
35	// fakeClockStart is the instant every fake clock starts at.
36	var fakeClockStart = time.Date(2026, time.November, 16, 12, 0, 0, 0, time.UTC)
37	
38	func newFakeClock(t *testing.T) *fakeClock {
39		t.Helper()
40		return &fakeClock{t: t, now: fakeClockStart, maxSleeps: 5000}
41	}
42	
43	// Now implements Clock.
44	func (c *fakeClock) Now() time.Time { return c.now }
45	
46	// Sleep implements Clock.
47	func (c *fakeClock) Sleep(ctx context.Context, d time.Duration) error {
48		c.t.Helper()
49		c.sleeps = append(c.sleeps, d)
50		if c.onSleep != nil {
51			c.onSleep(len(c.sleeps))
52		}
53		if d <= 0 {
54			c.t.Errorf("Sleep(%v): a wait must sleep for a positive duration", d)
55		}
56		if len(c.sleeps) > c.maxSleeps {
57			c.t.Errorf("more than %d sleeps: the code under test loops without end", c.maxSleeps)
58			return errors.New("fake clock: runaway loop")
59		}
60		if err := ctx.Err(); err != nil {
61			return err
62		}
63		c.now = c.now.Add(d)
64		return nil
65	}
66	
67	// elapsed is how far the clock moved since it started.
68	func (c *fakeClock) elapsed() time.Duration { return c.now.Sub(fakeClockStart) }
69	
70	func TestFakeClock(t *testing.T) {
71		t.Run("sleeping moves the clock and records the duration", func(t *testing.T) {
72			clk := newFakeClock(t)
73			for _, d := range []time.Duration{2 * time.Second, 3 * time.Second} {
74				if err := clk.Sleep(context.Background(), d); err != nil {
75					t.Fatalf("Sleep(%v) = %v", d, err)
76				}
77			}
78			if got, want := clk.elapsed(), 5*time.Second; got != want {
79				t.Errorf("elapsed = %v, want %v", got, want)
80			}
81			if len(clk.sleeps) != 2 {
82				t.Errorf("recorded %d sleeps, want 2", len(clk.sleeps))
83			}
84		})
85	
86		t.Run("a done context stops the sleep and leaves the clock alone", func(t *testing.T) {
87			clk := newFakeClock(t)
88			ctx, cancel := context.WithCancel(context.Background())
89			cancel()
90			if err := clk.Sleep(ctx, time.Second); !errors.Is(err, context.Canceled) {
91				t.Errorf("Sleep with a cancelled context = %v, want context.Canceled", err)
92			}
93			if clk.elapsed() != 0 {
94				t.Errorf("the clock moved by %v although the sleep was cancelled", clk.elapsed())
95			}
96		})
97	
98		t.Run("onSleep can cancel the context at the n-th sleep", func(t *testing.T) {
99			clk := newFakeClock(t)
100			ctx, cancel := context.WithCancel(context.Background())
101			defer cancel()
102			clk.onSleep = func(n int) {
103				if n == 2 {
104					cancel()
105				}
106			}
107			if err := clk.Sleep(ctx, time.Second); err != nil {
108				t.Fatalf("first Sleep = %v", err)
109			}
110			if err := clk.Sleep(ctx, time.Second); !errors.Is(err, context.Canceled) {
111				t.Errorf("second Sleep = %v, want context.Canceled", err)
112			}
113		})
114	}
